import { DotLoader, type DotPreset } from "@/components/application/selene/dot-loader";

const surface = { display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", borderRadius: 14, color: "light-dark(#1a1a1c, #ececee)", background: "light-dark(#fff, #1c1c1f)", boxShadow: "0 0 0 1px light-dark(rgb(0 0 0 / 0.06), rgb(255 255 255 / 0.09)), 0 2px 6px rgb(0 0 0 / 0.04)" } as const;
