const muted = "light-dark(#71717a, #a1a1aa)";

function InUse() {
  return (
    <div style={{ display: "grid", gap: 14, justifyItems: "center", width: "100%", maxWidth: 320 }}>
      <button type="button" style={{ ...surface, padding: "8px 14px", border: 0, font: "inherit", fontSize: 14, fontWeight: 500, cursor: "pointer" }}>
        <DotLoader grid={3} dot={3} gap={2} active={ink} inactive="light-dark(#e8e8ea, #3a3a3f)" label="Saving" />
        Saving
      </button>
      <div style={{ ...surface, width: "100%" }}>
        <span style={{ display: "grid", placeItems: "center", width: 34, height: 34, borderRadius: 9, background: "light-dark(#f1f3fb, #23263a)" }}>
          <DotLoader grid={4} preset="sweep" dot={3} gap={2} active="#3b5bdb" inactive="light-dark(#dde3f6, #34395a)" label="Indexing files" />
        </span>
        <span style={{ display: "grid", gap: 2 }}>
          <span style={{ fontSize: 14, fontWeight: 500 }}>Indexing files</span>
          <span style={{ fontSize: 12, color: muted, fontVariantNumeric: "tabular-nums" }}>1,204 of 3,380</span>
        </span>
      </div>
      <div style={{ display: "grid", justifyItems: "center", gap: 10, padding: "18px 0 4px" }}>
        <DotLoader grid={5} preset="ripple" dot={4} gap={3} frameTime={160} active={ink} inactive="light-dark(#e4e4e7, #34343a)" label="Loading projects" />
        <span style={{ fontSize: 13, color: muted }}>Loading projects</span>
      </div>
    </div>
  );
}

export default function DotLoaderDemo({ variant = "in-use" }: { variant?: string }) {
  if (variant === "in-use") return <InUse />;
  return <DotLoader grid={variant === "ripple" ? 5 : variant === "sweep" ? 4 : 3} preset={variant as DotPreset} dot={12} gap={8} active={ink} inactive="light-dark(#e4e4e7, #34343a)" />;
}

